  const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach(card => {
    const name = card.querySelector('span[id^="mntl-card-list-card--extendable_"]')?.textContent || card.textContent.split('Ratings')[0];
    const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
    const rating = ratingContainer?.querySelector('[class*="rating"]')?.getAttribute('aria-label') || ratingContainer?.textContent || 'N/A';
    const category = card.querySelector('[class*="category"]')?.textContent || '';
    const ratingsCount = card.querySelector('[id^="mntl-recipe-card-meta"] [class*="ratings-counts"]')?.textContent || '';
    results.push({name: name.trim().slice(0, 80), rating, category, ratingsCount});
  });
  return results;
}"}

