  const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach((card, idx) => {
    const ratingDiv = card.querySelector('[id^="mntl-recipe-star-rating"]');
    const widthStyle = ratingDiv?.getAttribute('style') || '';
    const title = card.querySelector('span')?.textContent?.trim() || '';
    const link = card.getAttribute('href') || '';
